@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderRepository orderRepository;
    OrderController(OrderRepository r) { this.orderRepository = r; }

    @GetMapping
    public Page<Order> getOrders(
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size) {
        int safeSize = Math.min(size, 100); // cap to protect the DB
        Pageable pageable = PageRequest.of(page, safeSize, Sort.by("createdAt").descending());
        return orderRepository.findAll(pageable); // Page includes total count
    }

    // Infinite scroll: Slice skips the count query
    @GetMapping("/feed")
    public Slice<Order> feed(@RequestParam(defaultValue = "0") int page) {
        return orderRepository.findByStatus("OPEN", PageRequest.of(page, 20));
    }
}
