// 1) custom interface
public interface OrderRepositoryCustom {
    List<Order> findWithFilters(String status, LocalDate from, BigDecimal minAmount);
}

// 2) implementation — note the Impl suffix
public class OrderRepositoryCustomImpl implements OrderRepositoryCustom {
    @PersistenceContext private EntityManager em;

    @Override
    public List<Order> findWithFilters(String status, LocalDate from, BigDecimal minAmount) {
        var cb = em.getCriteriaBuilder();
        var cq = cb.createQuery(Order.class);
        var root = cq.from(Order.class);
        var predicates = new ArrayList<Predicate>();
        if (status != null) predicates.add(cb.equal(root.get("status"), status));
        if (from != null)   predicates.add(cb.greaterThanOrEqualTo(root.get("createdAt"), from.atStartOfDay()));
        if (minAmount != null) predicates.add(cb.greaterThan(root.get("amount"), minAmount));
        cq.where(predicates.toArray(Predicate[]::new));
        return em.createQuery(cq).getResultList();
    }
}

// 3) main repository extends both
public interface OrderRepository
        extends JpaRepository<Order, Long>, OrderRepositoryCustom { }
