@Service
public class OrderService {
    private final InventoryRepository inventoryRepo;
    private final OrderRepository orderRepo;
    OrderService(InventoryRepository i, OrderRepository o) { inventoryRepo = i; orderRepo = o; }

    @Transactional // one atomic unit — both succeed or both roll back
    public Order checkout(Long productId, int qty) {
        var product = inventoryRepo.findById(productId).orElseThrow();
        if (product.getStock() < qty) throw new InsufficientStockException(); // rolls back
        product.decreaseStock(qty);
        return orderRepo.save(new Order(productId, qty));
    }

    @Transactional(readOnly = true) // skip dirty checking for reads
    public List<Order> recent(Long userId) {
        return orderRepo.findByUserIdOrderByCreatedAtDesc(userId);
    }
}
